from ..validate import validate_printspec

def _holes(holes): return '\n'.join(f"part = part.faces(\">Z\").workplane().pushPoints([({h['x']}, {h['y']})]).hole({h['diameter']})" for h in holes or [])
def generate_cadquery(spec):
    r=validate_printspec(spec)
    if not r['valid']: return {'supported':False,'code':'','message':'Validation failed: '+'; '.join(r['errors'][:3])}
    p=spec.get('part')
    if not p: return {'supported':False,'code':'','message':'Only part specs are supported.'}
    a=p['parameters']; header='# Generated by printspec 0.1.0\n# Review generated CAD before manufacturing.\nimport cadquery as cq\n\n'
    if p['type']=='rounded_rectangular_plate': return {'supported':True,'code':f"{header}length = {a['length']}\nwidth = {a['width']}\nheight = {a['thickness']}\ncorner_radius = {a['cornerRadius']}\n\npart = cq.Workplane(\"XY\").rounded_rect(length, width, corner_radius).extrude(height)\n{_holes(a.get('holes'))}\n"}
    if p['type']=='spacer_block': return {'supported':True,'code':f"{header}length = {a['length']}\nwidth = {a['width']}\nheight = {a['height']}\n\npart = cq.Workplane(\"XY\").box(length, width, height, centered=(True, True, False))\n{_holes(a.get('holes'))}\n"}
    return {'supported':False,'code':'','message':f"Unsupported part family: {p['type']}"}
